def page_hero(title,kicker,lead):
    return f'<nav class="breadcrumb container" aria-label="Ruta"><a href="index.html">Inicio</a><span>/</span><span>{kicker}</span></nav><section class="editorial-hero"><div class="container"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p class="lead">{lead}</p></div></section>'

def write_all():
    (ROOT/'elegir-transporte-carga.html').write_text(document('elegir-transporte-carga.html','Rampla, cama baja o carga consolidada | FACAI','Cómo elegir transporte de carga en Chile: diferencias entre rampla, cama baja, carga consolidada y proyectos. Qué revisar antes de cotizar con FACAI.',transport_choice_guide(page_hero)),encoding='utf-8')
    (ROOT/'guia-cotizar-transporte.html').write_text(document('guia-cotizar-transporte.html','Cómo cotizar transporte de carga en Chile | FACAI','Qué datos necesitas para cotizar transporte de carga: origen, destino, peso, dimensiones, equipo y accesos. Guía de FACAI, con base en Buin y cobertura nacional.',quotation_guide(page_hero)),encoding='utf-8')
    config={'email':'tlfacai@outlook.es','whatsapp':'56948004839','rutasEndpoint':None,'clientes':CLIENTS}
    (ROOT/'assets/configuracion.js').write_text('// Configuración pública. No colocar secretos aquí.\nwindow.FACAI_CONFIG = Object.freeze('+json.dumps(config,ensure_ascii=False,indent=2)+');\n',encoding='utf-8')
    (ROOT/'index.html').write_text(document('index.html',SITE['title'],SITE['description'],home()),encoding='utf-8')
    for file, source in PAGES.items():
        source=dict(source)
        settings=SERVICES_CONTENT.get(file)
        if settings:
            source['title']=settings['title']; source['description']=settings['description']
            source['main']=re.sub(r'<p class="lead">.*?</p>',lambda _: '<p class="lead">'+escape(settings['lead'])+'</p>',source['main'],count=1,flags=re.S)
        title=source['title']
        desc=source['description']
        main=source['main']
        main=main.replace('class="display"','class="display"')
        main=re.sub(r'href="(contacto.html[^\"]*)"',r'href="\1" data-quote',main)
        main=main.replace('class="service-link"','class="service-link text-link"')
        main=main.replace('+56 9 3469 1291','+56 9 4800 4839').replace('56934691291','56948004839')
        if file=='cobertura.html': main=main.replace('<section class="editorial-section paper">',map_section()+'<section class="editorial-section paper" id="detalle-cobertura">',1)
        if file=='experiencia.html': main=main.replace('</main>',gallery(list(range(1,40)), 'Industrias distintas. Soluciones a medida.', True)+client_band()+'</main>')
        # Keep supplied substantive copy, add operational imagery and the shared visual system.
        service=next((s for s in SERVICES if s[0]==file),None)
        if service:
            main=main.replace('<h3>Para preparar tu cotización</h3>', '<p><a href="elegir-transporte-carga.html">Compara rampla, cama baja y carga consolidada</a> · <a href="guia-cotizar-transporte.html">Antecedentes para cotizar</a></p><h3>Para preparar tu cotización</h3>',1)
            main=main.replace('</h1>','</h1>',1)
            main=main.replace('<section class="editorial-section paper">',f'<div class="service-photo container">{photo_slider(SERVICE_PHOTOS[file],service[2])}</div><section class="editorial-section paper">',1)
        if file=='cobertura.html': main=main.replace('</main>',source_notes()+'</main>')
        if file=='empresa.html': main=main.replace('mediante atención personalizada 24/7, seguridad operacional','mediante atención personalizada, seguridad operacional')
        if file=='servicios.html':
            def add_service_gallery(match):
                article=match.group(0)
                item=next((s for s in SERVICES if f'href="{s[0]}"' in article),None)
                return article.replace('class="service-card reveal">',f'class="service-card reveal">{photo_slider(SERVICE_PHOTOS[item[0]],item[2],True)}',1) if item else article
            main=re.sub(r'<article class="service-card reveal">.*?</article>',add_service_gallery,main,flags=re.S)
        if file=='privacidad.html':
            main=f'<main id="contenido">{page_hero("Tu información, con claridad.","Privacidad y contacto","Cómo usamos los datos que compartes al consultar por un traslado.")}<section class="editorial-section paper"><div class="container reading"><h2>Datos que decides compartir</h2><p>El cotizador prepara un resumen con la ruta, la carga y los datos de contacto que ingreses. FACAI utiliza la información que envíes para responder tu consulta y evaluar el servicio solicitado.</p><h2>Envío por WhatsApp o correo</h2><p>Completar el formulario no envía datos a FACAI. Al continuar en WhatsApp o en tu aplicación de correo podrás revisar y confirmar el envío. Desde ese momento también aplican las condiciones de privacidad del proveedor que elijas.</p><h2>Almacenamiento en este sitio</h2><p>Este sitio no incorpora cuentas de visitantes ni pagos. El formulario mantiene los datos en la página mientras la usas; no los guarda de forma permanente. Los datos de la cotización rápida pueden viajar a la página de contacto en la dirección de navegación si JavaScript está desactivado.</p><h2>Medición de visitas y recorridos</h2><p>Con tu consentimiento, Google Analytics mide páginas visitadas, profundidad de lectura, pasos del cotizador y clics de contacto. No enviamos a Analytics nombres, correos, teléfonos, rutas ingresadas ni el contenido de las solicitudes. Las direcciones de página se envían sin parámetros de consulta. Para distinguir visitas desde nuestros canales, podemos enviar etiquetas de campaña predefinidas, como LinkedIn, Instagram o Google Business; no se transmiten parámetros libres ni datos del cotizador. Google puede usar cookies de medición; no activamos funciones publicitarias ni Google Signals.</p><p>Puedes aceptar, rechazar o retirar el consentimiento desde «Preferencias de medición» en el pie de página. Guardamos esa preferencia en tu navegador. Rechazar la medición no limita el cotizador ni la navegación. Un clic en WhatsApp no acredita un mensaje enviado ni una venta.</p><h2>Cartografía y cálculo de rutas</h2><p>Al abrir el explorador, tu navegador solicita mapas a OpenFreeMap y relieve a Mapterhorn. Al calcular una ruta, las coordenadas de los puntos elegidos se envían al proveedor de ruteo configurado (OSRM en la revisión local). Esos servicios reciben datos técnicos como la dirección IP y pueden registrar la consulta según sus políticas. No se les envían los datos del cotizador ni tu ubicación GPS.</p><h2>Consultas sobre tus datos</h2><p>Para solicitar información, corrección o eliminación de los antecedentes compartidos con FACAI, escribe a <a href="mailto:tlfacai@outlook.es">tlfacai@outlook.es</a> o contacta al <a href="tel:+56948004839">+56 9 4800 4839</a>.</p><p>Actualizado el 10 de noviembre de 2026.</p></div></section></main>'
        (ROOT/file).write_text(document(file,title,desc,main),encoding='utf-8')
    contact=f'<main id="contenido">{page_hero("Tu carga tiene un destino.<br>Empecemos por aquí.","Cotiza con FACAI","Prepara tu solicitud y conversa directamente con el área comercial. Cada propuesta se ajusta a la carga, la ruta y las condiciones del servicio.")}<section class="contact-page section paper"><div class="container contact-grid"><aside><span class="eyebrow">ATENCIÓN COMERCIAL</span><h2>Una conversación.<br>El próximo paso.</h2><a href="{WA}" target="_blank" rel="noopener noreferrer" class="contact-channel">{icon("wa")}<span>WhatsApp comercial<strong>+56 9 4800 4839</strong></span>{icon("up")}</a><a class="contact-channel" href="mailto:tlfacai@outlook.es"><span>Correo comercial<strong>tlfacai@outlook.es</strong></span>{icon("up")}</a><p>Si no conoces las dimensiones o el equipo que necesitas, cuéntanos lo que ya sabes. Podemos comenzar desde ahí.</p><a class="text-link" href="preguntas-frecuentes.html">Dudas sobre tu traslado {icon("up")}</a></aside><div class="quote-card">{quote_form("page")}<noscript><p>Para usar el cotizador activa JavaScript, o <a href="{WA}">escríbenos directamente por WhatsApp</a>.</p></noscript></div></div></section></main>'
    (ROOT/'contacto.html').write_text(document('contacto.html','Cotiza transporte de carga en Chile | FACAI','Prepara tu solicitud de transporte de carga con FACAI. Cotiza carga, maquinaria y proyectos por WhatsApp al +56 9 4800 4839.',contact),encoding='utf-8')
    tms=f'<main id="contenido">{page_hero("Una nueva conexión<br>con tu logística.","FACAI TMS · Próximamente","Proyectamos una experiencia digital para acercarte a tu operación. El portal aún no está disponible y sus funcionalidades se comunicarán cuando estén definidas.")}{tms_section()}<section class="editorial-section paper"><div class="container editorial-grid"><div><span class="eyebrow">MIENTRAS TANTO</span><h2>Tu equipo FACAI,<br>a una conversación.</h2></div><div><p>Para consultas de operaciones, documentos o nuevas cotizaciones, contacta directamente al equipo comercial. El acceso a un portal de clientes se habilitará en una etapa posterior.</p><a class="btn btn-ink" href="{WA}" target="_blank" rel="noopener noreferrer">Contactar al área comercial {icon("wa")}</a></div></div></section></main>'
    (ROOT/'tms.html').write_text(document('tms.html','FACAI TMS: futuro portal de transporte | Próximamente','Conoce la próxima etapa digital de FACAI. El portal TMS aún no está habilitado. Contacta al equipo comercial para cotizaciones y consultas operacionales.',tms),encoding='utf-8')
    (ROOT/'facai-transporte.html').write_text('<!doctype html><html lang="es-CL"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src &#39;self&#39;; script-src &#39;self&#39; https://www.googletagmanager.com; style-src &#39;self&#39; &#39;unsafe-inline&#39;; img-src &#39;self&#39; data: blob: https://*.google-analytics.com https://*.analytics.google.com https://tiles.openfreemap.org https://tiles.mapterhorn.com; font-src &#39;self&#39;; connect-src &#39;self&#39; https://*.google-analytics.com https://*.analytics.google.com https://www.googletagmanager.com https://tiles.openfreemap.org https://tiles.mapterhorn.com https://router.project-osrm.org; worker-src &#39;self&#39; blob:; object-src &#39;none&#39;; base-uri &#39;self&#39;; form-action &#39;self&#39;; frame-src &#39;none&#39;; upgrade-insecure-requests"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FACAI Transporte y Logística</title><meta name="robots" content="noindex, follow"><link rel="canonical" href="https://facai.cl/"><meta http-equiv="refresh" content="0;url=index.html"></head><body><p>La página principal de FACAI está en <a href="index.html">Inicio</a>.</p></body></html>',encoding='utf-8')
    pages=[p.name for p in ROOT.glob('*.html') if p.name not in ['facai-transporte.html','404.html']]
